parameters.query:
SELECT coalesce(jsonb_agg(jsonb_build_object('job', 'SC-' || lpad(id::text, 4, '0'), 'status', status, 'attempts', attempts, 'updated_at', updated_at,
  'last_error', left(last_error, 300), 'master_rounds', master_rounds, 'title', script->>'title')), '[]') AS result
FROM (SELECT * FROM jobs WHERE status IN ('new', 'script_review', 'needs_human', 'revising', 'script_approved', 'video_review', 'video_editing', 'approved', 'awaiting_upload', 'scheduled') AND updated_at < now() - interval '24 hours' ORDER BY updated_at LIMIT 20) s;
